-- Summary:    corrective: stop down-tiering non-English academic literature as grey (ID searches re-targeted clinical); record the principle
--
-- This file is forward-only and immutable once committed. If a correction is
-- needed, emit a NEW data migration that compensates — do not edit this file.

BEGIN TRANSACTION;

-- Corrective (owner challenge 2026-07-24): non-English academic output was pre-classified as
-- 'grey' AT SEARCH-DESIGN TIME, while equivalent English-language work was targeted as 'clinical'.
-- Evidence of the bias in this session's own log: ES (exec 4) and JA (exec 41) searches targeted
-- 'clinical', but the two Indonesian searches (exec 51, 52) targeted 'grey' — even though the
-- material is peer-reviewed Indonesian academic literature (Jurnal TRAVE, ISTN) and university
-- research output (UNM eprints).
-- PRINCIPLE: a peer-reviewed journal or professional-body standard is academic/professional
-- literature in its own right regardless of language or Scopus/PubMed indexing. Non-indexation in
-- Western databases is an indexing fact, not an evidence-quality fact. Down-tiering by language is
-- a Western-indexing bias and is corrected here.
UPDATE search_executions
   SET target_evidence_type = 'clinical',
       findings_note = COALESCE(findings_note || ' | ', '') ||
         'CORRECTION: originally targeted evidence_type=grey; re-targeted to clinical. Indonesian peer-reviewed journal + university research output is academic literature in its own right — non-indexation in PubMed/Scopus is an indexing fact, not an evidence-quality fact.'
 WHERE exec_id IN (51, 52);

-- Also correct the candidate rows: these are academic sources, not grey ephemera.
UPDATE search_candidates
   SET notes = COALESCE(notes || ' | ', '') ||
       'Classified as academic literature (peer-reviewed ID journal / university research), NOT grey; tier_guess 3 reflects study design, not language of publication.'
 WHERE candidate_id IN (SELECT candidate_id FROM search_candidates WHERE exec_id IN (51,52));

COMMIT;
